-- Each user's Google connection (Gmail and Drive). Only the server reads it: no policy, so signed-in users
-- can't read their refresh token from the browser.
create table if not exists public.google_tokens (
  user_id uuid primary key references auth.users (id) on delete cascade,
  email text,
  refresh_token text not null,
  scope text,
  updated_at timestamptz not null default now()
);
alter table public.google_tokens enable row level security;

-- Who may use the tables. New Supabase projects don't grant this on their own: the server key (service_role)
-- reads and writes everything; signed-in users only their own rows (the policies above); anonymous visitors nothing.
grant usage on schema public to service_role, authenticated;
grant select, insert, update, delete on all tables in schema public to service_role;
grant select, insert, update, delete on all tables in schema public to authenticated;
revoke all on public.google_tokens from authenticated, anon;
grant usage, select on all sequences in schema public to service_role, authenticated;

-- Scheduled sync: Supabase calls the app every hour (Gmail imports every 2 hours in Jakarta time: 00:00–22:00 WIB,
-- plus resumes any unfinished partial import; Hyperliquid every 6 hours).
-- Turn on the pg_cron and pg_net extensions (Database → Extensions), put your app URL and CRON_SECRET in the
-- two lines below, and run this part once.
-- select cron.schedule(
--   'hourly-sync', '5 * * * *',
--   $$ select net.http_post(url := 'https://YOUR-APP.vercel.app/api/cron', headers := jsonb_build_object('Authorization', 'Bearer YOUR_CRON_SECRET'), timeout_milliseconds := 300000) $$
-- );
